    function syncOfficialLogoAvatarElement(containerEl, imgId, isSignedIn, initials = "") {
      if (!containerEl) return;
      if (typeof containerEl.setAttribute === "function") {
        containerEl.setAttribute("data-avatar-state", isSignedIn ? "signed-in" : "signed-out");
        containerEl.setAttribute("data-user-initials", initials || "");
        containerEl.setAttribute("data-official-logo", "true");
      }
      const hasImgChild = (typeof containerEl.querySelector === "function" && containerEl.querySelector("img")) ||
        (typeof containerEl.innerHTML === "string" && containerEl.innerHTML.includes("<img"));
      if (!hasImgChild && typeof containerEl.innerHTML === "string") {
        containerEl.innerHTML = `<img id="${imgId}" src="${SCREENSYNC_OFFICIAL_LOGO_DATA_URI}" alt="ScreenSync" class="ss-logo-avatar-img w-full h-full object-contain rounded-full select-none pointer-events-none" draggable="false" />`;
      }
    }

