    function normalizeAppKeyAlias(rawAppKey, fallbackAppName = null) {
      let raw = String(rawAppKey || "").trim();
      if (!raw && fallbackAppName) raw = String(fallbackAppName || "").trim();
      if (!raw) return "";
      const lowerRaw = raw.toLowerCase();
      // Preserve "site:<registrable-domain>" namespace without stripping domain TLD (AppIdentity.cs rule)
      if (lowerRaw.startsWith("site:")) {
        const hostPart = lowerRaw.slice(5).trim().replace(/^https?:\/\//, "").split("/")[0].replace(/^www\./, "");
        return hostPart ? `site:${hostPart}` : "";
      }
      if (PACKAGE_AND_BUNDLE_TO_KEY[lowerRaw]) return PACKAGE_AND_BUNDLE_TO_KEY[lowerRaw];
      // Strip Windows (\) and Unix (/) directory components if a full executable path was supplied
      if (raw.includes("\\") || raw.includes("/")) {
        const parts = raw.split(/[\\/]+/).filter(Boolean);
        if (parts.length > 0) raw = parts[parts.length - 1];
      }
      let k = raw.trim().toLowerCase();
      if (PACKAGE_AND_BUNDLE_TO_KEY[k]) return PACKAGE_AND_BUNDLE_TO_KEY[k];
      if (k === "fb_messenger" || k === "facebook_messenger" || k === "messenger_kids" || k === "messenger.exe") return "messenger";
      if (k === "fb_lite" || k === "facebook_lite" || k === "fb lite") return "fblite";
      if (k === "ig" || k === "instagram.exe" || k === "instagram.app") return "instagram";
      if (k === "yt" || k === "youtube_shorts" || k === "youtube.app" || k === "youtube.exe") return "youtube";
      if (k === "wa" || k === "whatsapp.exe" || k === "whatsapp.app") return "whatsapp";
      if (k === "chrome.exe" || k === "google chrome" || k === "googlechrome") return "chrome";
      if (k === "claude.exe" || k === "claude.app") return "claude";
      // Strip trailing executable/bundle extensions (.exe, .app, .msi, .bat) while preserving leading-dot names
      const extMatch = k.match(/^(.+)\.(exe|app|msi|bat|cmd|lnk)$/i);
      if (extMatch && extMatch[1].length > 0) {
        k = extMatch[1];
      }
      if (PACKAGE_AND_BUNDLE_TO_KEY[k]) return PACKAGE_AND_BUNDLE_TO_KEY[k];
      return k.replace(/[^a-z0-9_]/g, "_").replace(/^_+|_+$/g, "");
    }

    function buildFallbackAppIconSvg(appName = "App", category = "Other") {
      const cleanName = String(appName || "App").trim();
      const words = cleanName.split(/\s+/).filter(Boolean);
      const monogram = (words.length >= 2 ? (words[0][0] + words[1][0]) : cleanName.slice(0, 2)).toUpperCase() || "AP";
      const bgMap = {
        "Social networking": "from-[#2563EB] to-[#38BDF8]",
        "Entertainment": "from-[#6366F1] to-[#EC4899]",
        "Productivity & finance": "from-[#0EA5E9] to-[#10B981]"
      };
      const gradCls = bgMap[category] || "from-[#334155] to-[#475569]";
      return `<div class="w-10 h-10 rounded-xl bg-gradient-to-br ${gradCls} flex items-center justify-center text-white font-extrabold text-xs shrink-0 border border-white/15 select-none" data-fallback-icon="true" aria-hidden="true">${monogram}</div>`;
    }

    function getAppLogoHtml(appKey, appName = "", customIcon = null) {
      const normKey = normalizeAppKeyAlias(appKey);
      if (customIcon && typeof customIcon === "string") {
        const trimmed = customIcon.trim();
        if (trimmed.startsWith("<svg")) return trimmed;
        if (trimmed.startsWith("data:image/")) {
          const safeAlt = String(appName || APP_METADATA[normKey]?.name || normKey || "App").replace(/"/g, "&quot;");
          return `<img src="${trimmed}" alt="${safeAlt}" class="w-10 h-10 rounded-xl object-cover shrink-0" data-native-icon="true" />`;
        }
      }
      if (APP_LOGOS[normKey]) return APP_LOGOS[normKey];
      const meta = APP_METADATA[normKey];
      if (meta && meta.customIconHtml) return meta.customIconHtml;
      return buildFallbackAppIconSvg(appName || meta?.name || normKey || "App", meta?.category || "Other");
    }

