    const STABLE_INSTALLATION_STORAGE_KEY = "screensync_stable_installation_profile_v2";
    const AUTH_SESSION_STORAGE_KEY = "screensync_authenticated_session_v2";
    const AUTH_LOGOUT_FLAG_KEY = "screensync_explicit_logout_flag_v2";
    const DESIGN_STYLE_STORAGE_KEY = "screensync_design_style_pref_v2";
