          nativeUsageApis: ["AppKit.NSWorkspace.frontmostApplication", "CoreGraphics.CGWindowListCopyWindowInfo"],
          screenActivityApis: ["ApplicationServices.AXUIElement", "ScreenCaptureKit.SCStream (CGRequestScreenCaptureAccess)", "BrowserWebExtension"],
          appDiscoveryApis: ["AppKit.NSWorkspace.runningApplications", "Foundation.FileManager (/Applications)"],
          supportsAggregateUsageStats: true,
          supportsPerSessionReelDetection: true,
